import argparse


def createparser():
    """Create an ArgumentParser for the pysemver CLI."""
    parser = argparse.ArgumentParser(prog='pysemver', description='Semantic Versioning utilities')
    parser.add_argument('version', help='The version string to manipulate')
    group = parser.add_mutually_exclusive_group()
    group.add_argument('--bump-major', action='store_true', help='Bump major version')
    group.add_argument('--bump-minor', action='store_true', help='Bump minor version')
    group.add_argument('--bump-patch', action='store_true', help='Bump patch version')
    group.add_argument('--bump-prerelease', metavar='TOKEN', nargs='?', const='rc', help='Bump prerelease, optional token')
    group.add_argument('--bump-build', metavar='TOKEN', nargs='?', const='build', help='Bump build, optional token')
    return parser


def process(args):
    """Process parsed arguments and output the resulting version."""
    version = args.version
    if args.bump_major:
        return bump_major(version)
    if args.bump_minor:
        return bump_minor(version)
    if args.bump_patch:
        return bump_patch(version)
    if args.bump_prerelease is not None:
        token = args.bump_prerelease if args.bump_prerelease != '' else 'rc'
        return bump_prerelease(version, token)
    if args.bump_build is not None:
        token = args.bump_build if args.bump_build != '' else 'build'
        return bump_build(version, token)
    # default: just print the original version
    return version


def main():
    parser = createparser()
    args = parser.parse_args()
    result = process(args)
    print(result)
